					if turnOrder[a].score.MageTower>0 and forTheCouncil~=true then
						local towerRate=heroChallengeActive(a)==true and turnOrder[a].mage=="Tovak" and 4 or 2
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.MageTower, "{en} Mage Tower(s): +{ru} Башня мага: +{zh-cn}个法师塔已征服: +{ko} 마법사의 탑: +{es} Torres de Magos: +{fr} Tours des Mages: +{pt-br} Torres de Mago: +{de} Magierturm(e): +", turnOrder[a].score.MageTower*towerRate})
						totalScore=totalScore+(turnOrder[a].score.MageTower*towerRate)
					end
					if gStates.gameScenario~="Conquer and Hold" then
						if turnOrder[a].score.Monastery>0 and forTheCouncil~=true then
							local monasteryRate=heroChallengeActive(a)==true and turnOrder[a].mage=="Tovak" and 4 or 2
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.Monastery, "{en} Monastery(s): +{ru} Монастырь: +{zh-cn}个修道院已焚毁: +{ko} 수도원: +{es} Monasterios: +{fr} Monastères: +{pt-br} Monastérios: +{de} Kloster(s): +", turnOrder[a].score.Monastery*monasteryRate})
							totalScore=totalScore+(turnOrder[a].score.Monastery*monasteryRate)
						end
						if turnOrder[a].score.VolkareCamp>0 and forTheCouncil~=true then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.VolkareCamp, "{en} Volkare Pursuits: +{ru} Охоты на Волкара: +{zh-cn}沃卡里追击： +{ko} 볼케어 진영 추적: +{es} Persecuciones de Volkare: +{fr} Volkare Poursuites: +{pt-br} Volkare Persegue: +{de} Volkare Verfolgungen: +", turnOrder[a].score.VolkareCamp})
							totalScore=totalScore+turnOrder[a].score.VolkareCamp
						end
						if turnOrder[a].score.gConqueror>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Conqueror: +{ru}Великий завоеватель: +{zh-cn}至高征服者： +{ko}위대한 정복자: +{es}Mayor Conquistador: +{fr}Plus Grand Conquérant: +{pt-br}Maior Conquistador: +{de}Größter Eroberer: +", turnOrder[a].score.gConqueror})
							totalScore=totalScore+turnOrder[a].score.gConqueror
						end
					end
					updateScorePannel("Conqueror", lineFeed, assembledText)
				end

				--Against the Horsemen competitive scoring: +6 per personal kill and the special Slayer title.
				if againstHorsemen and gStates.coop==0 then
					assembledText="" lineFeed=0
					local defeated=turnOrder[a].score.HorsemenDefeated or 0
					if defeated>0 then
						local horsemenLabel=defeated==1 and "{en} Horseman: +{ru} Horseman: +{zh-tw} Horseman: +{zh-cn} Horseman: +{ko} Horseman: +{es} Horseman: +{fr} Horseman: +{pt-br} Horseman: +{de} Horseman: +" or "{en} Horsemen defeated: +{ru} Horsemen defeated: +{zh-tw} Horsemen defeated: +{zh-cn} Horsemen defeated: +{ko} Horsemen defeated: +{es} Horsemen defeated: +{fr} Horsemen defeated: +{pt-br} Horsemen defeated: +{de} Horsemen defeated: +"
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{defeated,horsemenLabel,defeated*6})
						totalScore=totalScore+(defeated*6)
					end
					if (turnOrder[a].score.gHorsemanSlayer or 0)>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Greatest Horseman Slayer: +{ru}Greatest Horseman Slayer: +{zh-tw}Greatest Horseman Slayer: +{zh-cn}Greatest Horseman Slayer: +{ko}Greatest Horseman Slayer: +{es}Greatest Horseman Slayer: +{fr}Greatest Horseman Slayer: +{pt-br}Greatest Horseman Slayer: +{de}Greatest Horseman Slayer: +",turnOrder[a].score.gHorsemanSlayer})
						totalScore=totalScore+turnOrder[a].score.gHorsemanSlayer
					end
					UI.setAttribute("TezlaScoreHeadingText","text","{en}Horsemen{ru}Horsemen{zh-tw}Horsemen{zh-cn}Horsemen{ko}Horsemen{es}Horsemen{fr}Horsemen{pt-br}Horsemen{de}Horsemen")
					updateScorePannel("Tezla",lineFeed,assembledText)
				end

				--Against the Dragon competitive scoring. Every Shield on a coloured head is one
				--level reduced and therefore +1 score. Each head also awards one +5 Greatest Slayer.
				if againstDragon and gStates.coop==0 then
					assembledText="" lineFeed=0
					local dragonPlayer=dragonScoreSummary.byMage[turnOrder[a].mage] or {levels=0,slayerBonus=0,slayerHeads={}}
					if dragonPlayer.levels>0 then
						local dragonScoreLabel=apocalypseHere and "{en} Head Slayer score: +{ru} Head Slayer score: +{zh-tw} Head Slayer score: +{zh-cn} Head Slayer score: +{ko} Head Slayer score: +{es} Head Slayer score: +{fr} Head Slayer score: +{pt-br} Head Slayer score: +{de} Head Slayer score: +" or "{en} Dragon Head Level(s) Reduced: +{ru} Dragon Head Level(s) Reduced: +{zh-tw} Dragon Head Level(s) Reduced: +{zh-cn} Dragon Head Level(s) Reduced: +{ko} Dragon Head Level(s) Reduced: +{es} Dragon Head Level(s) Reduced: +{fr} Dragon Head Level(s) Reduced: +{pt-br} Dragon Head Level(s) Reduced: +{de} Dragon Head Level(s) Reduced: +"
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{dragonPlayer.levels,dragonScoreLabel,dragonPlayer.levels})
						totalScore=totalScore+dragonPlayer.levels
					end
					if dragonPlayer.slayerBonus>0 then
						assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{#dragonPlayer.slayerHeads,"{en} Greatest Head Slayer bonus(es): +{ru} Greatest Head Slayer bonus(es): +{zh-tw} Greatest Head Slayer bonus(es): +{zh-cn} Greatest Head Slayer bonus(es): +{ko} Greatest Head Slayer bonus(es): +{es} Greatest Head Slayer bonus(es): +{fr} Greatest Head Slayer bonus(es): +{pt-br} Greatest Head Slayer bonus(es): +{de} Greatest Head Slayer bonus(es): +",dragonPlayer.slayerBonus})
						totalScore=totalScore+dragonPlayer.slayerBonus
					end
					UI.setAttribute("TezlaScoreHeadingText","text",apocalypseHere and "{en}Head Slayer score{ru}Head Slayer score{zh-tw}Head Slayer score{zh-cn}Head Slayer score{ko}Head Slayer score{es}Head Slayer score{fr}Head Slayer score{pt-br}Head Slayer score{de}Head Slayer score" or "{en}Dragon{ru}Dragon{zh-tw}Dragon{zh-cn}Dragon{ko}Dragon{es}Dragon{fr}Dragon{pt-br}Dragon{de}Dragon")
					updateScorePannel("Tezla",lineFeed,assembledText)
				end

				--Total Score
				if (gStates.coop==0 or gStates.WarOfFourComp==true) then
					UI.setAttribute("CompScoreData", "active", "true")
					UI.setAttribute("Total"..pannel.."ScoreCell", "active", "true")
					if forTheCouncil then
						local resultSuffix=councilMissionResult~="" and joinLang({"\n", councilMissionResult}) or ""
						UI.setAttribute("Total"..pannel.."ScoreText", "text", joinLang({translateWord[turnOrder[a].mage], "{en}'s Final Score: {ru}'s Final Score: {zh-tw}'s Final Score: {zh-cn}'s Final Score: {ko}'s Final Score: {es}'s Final Score: {fr}'s Final Score: {pt-br}'s Final Score: {de}'s Final Score: ", totalScore, resultSuffix}))
					else
						UI.setAttribute("Total"..pannel.."ScoreText", "text", joinLang({translateWord[turnOrder[a].mage], "{en}'s Final Fame: {ru} имеет итого Славы: {zh-cn}的最终名望： {ko} 의 최종 명성: {es} Fama Final: {fr} Gloire Finale: {pt-br} Fama Final: {de}End-Ruhm: ", totalScore}))
					end
					if gStates.gameScenario=="Conquer and Hold" then UI.setAttribute("Total"..pannel.."ScoreText", "text", joinLang({translateWord[turnOrder[a].mage], "{en}'s Final VP: {ru} имеет итого ПО: {zh-cn}的最终分数： {ko} 의 최종 승점: {es} Vicepresidente Final: {fr} Vice-Président Final de: {pt-br} Pontos de Vitória Final: {de}s End-VP: ", totalScore})) end
					turnOrder[a].score.finalScore=totalScore
				end
				pannel=pannel+1
			else
				if forTheCouncil~=true then
					assembledText="" lineFeed=0
					if gStates.positionMageKnight[5]~="Volkare" then
						--First Reconnaissance uses normal Achievement scoring only; it does not use Solo Conquest efficiency bonuses.
						if gStates.gameScenario~="First Reconnaissance" then
						--Efficiency
						if gStates.currentRound<gStates.rounds and gStates.gameScenario~="The Lost Relic Blitz" then
							local c=30
							if gStates.gameScenario=="The Gauntlet" then c=40 end
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{gStates.rounds-gStates.currentRound, "{en} Round(s) still to go: +{ru} Оставшиеся Раунды: +{zh-cn}个未开始的轮次： +{ko} 남은 라운드: +{es} Rondas Aún por Hacer: +{fr} Rounds Encore à Faire: +{pt-br} Rodadas ainda a completar: +{de} Noch ausstehende Runde(n): +", ((gStates.rounds-gStates.currentRound)*c)})
							coopScore=coopScore+((gStates.rounds-gStates.currentRound)*c)
						end
						if turnOrder[a].score.CardsLeft>0 then
							local c=1
							if gStates.gameScenario=="The Gauntlet" then c=2 end
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.CardsLeft, "{en} Dummy Card(s) Left: +{ru} Карт у виртуального игрока: +{zh-cn}虚拟玩家剩余牌池量： +{ko} 남은 가상 플레이어의 카드: + {es} Cartas Falsas Restantes: +{fr} Cartes Factices Restantes: +{pt-br} Cartas Restantes do Jog. Fic.: +{de} Dummy-Karte(n) links: +", turnOrder[a].score.CardsLeft*c})
							coopScore=coopScore+turnOrder[a].score.CardsLeft*c
						end
						if gStates.endRoundCalled==false then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Round End Not Called: +5{ru}Конец последнего Раунда не был объявлен: +5{zh-cn}最后一轮中没有声明本轮结束： +5{ko}라운드 종료 선언되지 않음: +5{es}Final de Ronda no Llamado: +5{fr}Fin de Manche non Appelée: +5{pt-br}Rodada final Não chamada: +5{de}Rundenende nicht ausgerufen: +5"})
							coopScore=coopScore+5
						end
						if gStates.gameScenario=="Druid Nights" and gStates.playerCount==1 then
							local rituals=0
							for _,details in pairs(turnOrder) do if details.mage~=gStates.positionMageKnight[5] then rituals=details.druidNightsRitualCount or 0 break end end
							if rituals>0 then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{rituals,"{en} Incantation(s): +{ru} Incantation(s): +{zh-tw} Incantation(s): +{zh-cn} Incantation(s): +{ko} Incantation(s): +{es} Incantation(s): +{fr} Incantation(s): +{pt-br} Incantation(s): +{de} Incantation(s): +",rituals*15})
								coopScore=coopScore+(rituals*15)
							end
						end
						if gStates.gameScenario=="Against the Apocalypse Blitz" and gStates.coop==1 and gStates.endGameAchieved=="true" then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Beat the Scenario: +15{ru}Прохождение сценария: +15{zh-tw}通關劇本：+15{zh-cn}通关剧本：+15{ko}시나리오 클리어: +15{es}Superar el escenario: +15{fr}Victoire dans le scénario : +15{pt-br}Superou o cenário: +15{de}Szenario gemeistert: +15"})
							coopScore=coopScore+15
						end
						updateScorePannel("Efficiency", lineFeed, assembledText)
						end
					else
						--Volkare
						if gStates.volkareWon~=true then
							local volkareCombatLevel={"Daring", "Heroic", "Legendary"}
							local volkareRaceLevel={"Fair", "Tight", "Thrilling"}
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{translateWord[volkareCombatLevel[gStates.volkareCombatLevel]], "{en} Volkare Combat Level: +(({ru} Уровень битвы Волкара: +(({zh-cn}沃卡里战斗等级： +（（{ko} 볼케어 전투 레벨: +(({es} Nivel de Combate Volkare: +(({fr} Niveau de Combat Volkare: +(({pt-br} Nível de Combate de Volkare: +(({de} Volkare Kampfstufe: +((", (gStates.volkareCombatLevel*10)+20})
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{turnOrder[a].score.CardsLeft, "{en} Volkare Card(s) Left: +{ru} Карт у Волкара: +{zh-cn}沃卡里卡池剩余： +{ko} 남은 볼케어 카드: +{es} Cartas Volkare Restantes: +{fr} Cartes Volkare Restantes: +{pt-br} Cartas de Volkare Restantes: +{de} Volkare Karte(n) übrig: +", (turnOrder[a].score.CardsLeft*2), ")"})
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{translateWord[volkareRaceLevel[gStates.volkareRaceLevel]], "{en} Volkare Race Level: x{ru} Уровень гонки Волкара: x{zh-cn}沃卡里移动等级： x{ko} 볼케어 레이스 레벨: x{es} Nivel de Carrera Volkare: x{fr} Niveau de Course Volkare: x{pt-br} Nível de Corrida de Volkare: +{de} Volkare Ethnie Stufe: x", (((gStates.volkareRaceLevel-1)/2)+1), ")"})
							coopScore=coopScore+((((gStates.volkareCombatLevel*10)+20)+(turnOrder[a].score.CardsLeft*2))*(((gStates.volkareRaceLevel-1)/2)+1))
							updateScorePannel("Volkare", lineFeed, assembledText)
						end
					end

					--Against the Horsemen cooperative/solo scenario bonuses. Standard cooperative Achievement
					--scoring above already supplies the lowest Fame base and the best score in each category.
					if againstHorsemen then
						assembledText="" lineFeed=0
						if horsemenSummary.total>0 then
							local horsemenLabel=horsemenSummary.total==1 and "{en} Horseman: +{ru} Horseman: +{zh-tw} Horseman: +{zh-cn} Horseman: +{ko} Horseman: +{es} Horseman: +{fr} Horseman: +{pt-br} Horseman: +{de} Horseman: +" or "{en} Horsemen defeated: +{ru} Horsemen defeated: +{zh-tw} Horsemen defeated: +{zh-cn} Horsemen defeated: +{ko} Horsemen defeated: +{es} Horsemen defeated: +{fr} Horsemen defeated: +{pt-br} Horsemen defeated: +{de} Horsemen defeated: +"
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{horsemenSummary.total,horsemenLabel,horsemenSummary.total*4})
							coopScore=coopScore+(horsemenSummary.total*4)
						end
						if gStates.playerCount>1 and againstHorsemenEveryScoringPlayerDefeatedOne(horsemenSummary)==true then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Each player defeated a Horseman: +6{ru}Each player defeated a Horseman: +6{zh-tw}Each player defeated a Horseman: +6{zh-cn}Each player defeated a Horseman: +6{ko}Each player defeated a Horseman: +6{es}Each player defeated a Horseman: +6{fr}Each player defeated a Horseman: +6{pt-br}Each player defeated a Horseman: +6{de}Each player defeated a Horseman: +6"})
							coopScore=coopScore+6
						end
						if horsemenSummary.total>=4 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}All Horsemen defeated: +15{ru}All Horsemen defeated: +15{zh-tw}All Horsemen defeated: +15{zh-cn}All Horsemen defeated: +15{ko}All Horsemen defeated: +15{es}All Horsemen defeated: +15{fr}All Horsemen defeated: +15{pt-br}All Horsemen defeated: +15{de}All Horsemen defeated: +15"})
							coopScore=coopScore+15
						end
						UI.setAttribute("TezlaScoreHeadingText","text","{en}Horsemen{ru}Horsemen{zh-tw}Horsemen{zh-cn}Horsemen{ko}Horsemen{es}Horsemen{fr}Horsemen{pt-br}Horsemen{de}Horsemen")
						local temp=pannel
						pannel=1
						UI.setAttribute("Tezla1ScoreCell","columnSpan","4")
						UI.setAttribute("Tezla1ScoreText","alignment","MiddleCenter")
						updateScorePannel("Tezla",lineFeed,assembledText)
						pannel=temp
					end

					--Against the Dragon cooperative/solo goal scoring. Generic efficiency scoring above
					--already handles early Rounds, Dummy cards left, and the uncalled End-of-Round +5.
					if againstDragon then
						assembledText="" lineFeed=0
						if apocalypseHere and horsemenSummary.total>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{horsemenSummary.total,"{en} Horsemen defeated: +{ru} Horsemen defeated: +{zh-tw} Horsemen defeated: +{zh-cn} Horsemen defeated: +{ko} Horsemen defeated: +{es} Horsemen defeated: +{fr} Horsemen defeated: +{pt-br} Horsemen defeated: +{de} Horsemen defeated: +",horsemenSummary.total*3})
							coopScore=coopScore+(horsemenSummary.total*3)
						end
						if apocalypseHere and gStates.playerCount>1 and againstHorsemenEveryScoringPlayerDefeatedOne(horsemenSummary)==true then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Each player defeated a Horseman: +5{ru}Each player defeated a Horseman: +5{zh-tw}Each player defeated a Horseman: +5{zh-cn}Each player defeated a Horseman: +5{ko}Each player defeated a Horseman: +5{es}Each player defeated a Horseman: +5{fr}Each player defeated a Horseman: +5{pt-br}Each player defeated a Horseman: +5{de}Each player defeated a Horseman: +5"})
							coopScore=coopScore+5
						end
						if dragonScoreSummary.defeatedHeads>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{dragonScoreSummary.defeatedHeads,"{en} Dragon Head(s) Defeated: +{ru} Dragon Head(s) Defeated: +{zh-tw} Dragon Head(s) Defeated: +{zh-cn} Dragon Head(s) Defeated: +{ko} Dragon Head(s) Defeated: +{es} Dragon Head(s) Defeated: +{fr} Dragon Head(s) Defeated: +{pt-br} Dragon Head(s) Defeated: +{de} Dragon Head(s) Defeated: +",dragonScoreSummary.defeatedHeads*5})
							coopScore=coopScore+(dragonScoreSummary.defeatedHeads*5)
						end
						if dragonScoreSummary.defeatedHeads>=4 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}All Dragon Heads defeated: +15{ru}All Dragon Heads defeated: +15{zh-tw}All Dragon Heads defeated: +15{zh-cn}All Dragon Heads defeated: +15{ko}All Dragon Heads defeated: +15{es}All Dragon Heads defeated: +15{fr}All Dragon Heads defeated: +15{pt-br}All Dragon Heads defeated: +15{de}All Dragon Heads defeated: +15"})
							coopScore=coopScore+15
						end
						UI.setAttribute("TezlaScoreHeadingText","text",apocalypseHere and "{en}Apocalypse{ru}Apocalypse{zh-tw}Apocalypse{zh-cn}Apocalypse{ko}Apocalypse{es}Apocalypse{fr}Apocalypse{pt-br}Apocalypse{de}Apocalypse" or "{en}Dragon{ru}Dragon{zh-tw}Dragon{zh-cn}Dragon{ko}Dragon{es}Dragon{fr}Dragon{pt-br}Dragon{de}Dragon")
						local temp=pannel
						pannel=1
						UI.setAttribute("Tezla1ScoreCell","columnSpan","4")
						UI.setAttribute("Tezla1ScoreText","alignment","MiddleCenter")
						updateScorePannel("Tezla",lineFeed,assembledText)
						pannel=temp
					end

					--Relic Score
					if gStates.gameScenario=="The Lost Relic Blitz" then
						assembledText="" lineFeed=0
						if foundRelic>0 then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{foundRelic, "{en} Relic(s) Found: +{ru} Реликвия найдена: +{zh-cn}个圣器已收集: +{ko} 발견한 유물: +{es} Reliquias Encontradas: +{fr} Reliques Trouvées: +{pt-br} Relíquias Encontradas: +{de} Relikt(e) gefunden: +", (foundRelic*5)})
							coopScore=coopScore+(foundRelic*5)
						end
						if gStates.playersRef~=5 then
							local EveryRelic=true
							for b=1, #turnOrder, 1 do
								if turnOrder[b].mage~=gStates.positionMageKnight[5] then
									if turnOrder[b].score.Relic==0 then EveryRelic=false break end
								end
							end
							if EveryRelic==true then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Every player collected a Relic: +5{ru}Каждый игрок собрал реликвию: +5{zh-cn}每位玩家收集一件圣器: +5{ko}모든 플레이어 유물 수집: +5{es}Cada Jugador Recogió una Reliquia: +5{fr}Chaque Joueur a Récupéré une Relique: +5{pt-br}Cada Jogador coletou uma Relíquia: +5{de}Jeder Spieler hat eine Reliquie gesammelt: +5"})
								coopScore=coopScore+5
							end
						end
						if foundRelic==gStates.cityTiles then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}All relics collected: +10{ru}Все реликвии собраны: +10{zh-cn}收集所有圣器: +10{ko}모든 유물 수집됨: +10{es}Todas las Reliquias Recolectadas: +10{fr}Toutes les Reliques Collectées: +10{pt-br}Todas Relíquias Coletadas: +10{de}Alle gesammelten Reliquien: +10"})
							coopScore=coopScore+10
						end
						local temp=pannel
						pannel=1
						UI.setAttribute("Relic1ScoreCell", "columnSpan", "4")
						UI.setAttribute("Relic1ScoreText", "alignment", "MiddleCenter")
						updateScorePannel("Relic", lineFeed, assembledText)
						pannel=temp
					end

					--City Coop Score. Fractured Lands explicitly does not use City scoring.
					if fracturedLandsNoCityScore~=true and (gStates.defeatedCities.amount>0 or gStates.gameScenario=="The Gauntlet") then
						assembledText="" lineFeed=0
						local cityValue=10
						if gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" then cityValue=20 end
						if gStates.gameScenario=="Volkare's Quest" then cityValue=5 end
						if gStates.gameScenario~="The Gauntlet" then
							assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{gStates.defeatedCities.amount, "{en} Conquered City(s): +{ru} Захваченный Город: +{zh-cn}个城市已征服: +{ko} 정복한 도시: +{es} Ciudades Conquistadas: +{fr} Villes Conquises: +{pt-br} Cidades Conquistadas: +{de} Eroberte Stadt(en): +", (gStates.defeatedCities.amount*cityValue)})
							coopScore=coopScore+(gStates.defeatedCities.amount*cityValue)
						end
						if gStates.gameScenario~="Volkare's Return" and gStates.gameScenario~="Volkare's Return Blitz" and gStates.gameScenario~="Volkare's Quest" then
							if gStates.playersRef~=5 and gStates.allLeaderCheck==true then
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}Each Player is a Leader of a City: +10{ru}Каждый игрок владеет Городом: +10{zh-cn}每个玩家都是一个城市的领袖: +10{ko}각 플레이어가 도시 지도자: +10{es}Cada Jugador es un Líder de una Ciudad: +10{fr}Chaque Joueur est un Chef de Ville: +10{pt-br}Cada jogador é um líder de uma cidade: +10{de}Jeder Spieler ist ein Anführer einer Stadt: +10"})
								coopScore=coopScore+10
							end
							if gStates.defeatedCities.amount==gStates.cityTiles then--+gStates.megapolis
								assembledText,lineFeed=appendScoreLine(assembledText,lineFeed,{"{en}All Cities are Conquered: +15{ru}Все города захвачены: +15{zh-cn}征服了所有城市: +15{ko}모든 도시 정복됨: +15{es}Todas las Ciudades son Conquistadas: +15{fr}Toutes les Villes Sont Conquises: +15{pt-br}Todas Cidades Conquistadas: +15{de}Alle Städte sind erobert: +15"})
								coopScore=coopScore+15
							end
						end
						if gStates.gameScenario=="The Gauntlet" and gStates.endGameAchieved=="true" then
							assembledText="{en}Entered the Red City: +10\nBought the Artifact: +10{ru}Красный город посещен: +10\nАртефакт куплен: +10{zh-cn}进入红色城市： +10\n购买圣器： +10{ko}적색 도시 입장: +10\n유물 구입: +10{es}Entró en la Ciudad Roja: +10\nCompró la Reliquia: +10{fr}Entrée dans la Ville Rouge: +10\nAcheté la Relique: +10{pt-br}Entrou na Cidade Vermelha:+10\nComprou a Relíquia: +10{de}Die Rote Stadt betreten: +10\nKaufte das Artefakt: +10"
